use gluesql_core::store::{StoreMut, DataRow};
use gluesql_core::data::Value;
use gluesql_core::error::Result;
use futures::stream::TryStreamExt;

fn validate_column_type(store: &dyn StoreMut, table_name: &str, column_name: &str, expected_type: &str) -> Result<()> {
    let mut rows = store.scan(table_name).try_stream()?;
    while let Some(row) = rows.next().await {
        let row = row?;
        if let Some(value) = row.get(column_name) {
            if !matches_value(value, expected_type) {
                return Err(format!("Mismatched type for column '{}': expected '{}', got '{}'", column_name, expected_type, value).into());
            }
        }
    }
    Ok(())
}

fn matches_value(value: &Value, expected_type: &str) -> bool {
    match value {
        Value::Int(i) => expected_type == "INT" || expected_type == "INTEGER",
        Value::BigInt(i) => expected_type == "BIGINT",
        Value::Real(f) => expected_type == "REAL" || expected_type == "FLOAT",
        Value::Text(s) => expected_type == "TEXT",
        Value::Bool(b) => expected_type == "BOOLEAN" || expected_type == "BOOL",
        Value::Null => expected_type == "NULL",
        _ => false,
    }
}

fn analyze_tokens(tokens: &[String]) -> Vec<(String, TokenType)> {
    let mut result = Vec::new();
    for token in tokens {
        let token_type = determine_token_type(token);
        result.push((token.clone(), token_type));
    }
    result
}

enum TokenType {
    Kanji,
    Hiragana,
    Katakana,
    Alphabet,
    Number,
    Other,
}

fn determine_token_type(token: &str) -> TokenType {
    let mut has_kanji = false;
    let mut has_hiragana = false;
    let mut has_katakana = false;
    let mut has_alphabet = false;
    let mut has_number = false;

    for c in token.chars() {
        let ctype = get_ctype(c);
        match ctype {
            'M' => has_kanji = true,
            'H' => has_hiragana = true,
            'I' => has_hiragana = true,
            'K' => has_katakana = true,
            'A' => has_alphabet = true,
            'N' => has_number = true,
            _ => {}
        }
    }

    if has_kanji {
        return TokenType::Kanji;
    } else if has_hiragana {
        return TokenType::Hiragana;
    } else if has_katakana {
        return TokenType::Katakana;
    } else if has_alphabet {
        return TokenType::Alphabet;
    } else if has_number {
        return TokenType::Number;
    } else {
        return TokenType::Other;
    }
}

use ssi_eip712::{value::Value, ty::{TypeRef, Types}, hashing::TypedDataHashError};

fn validate_value(value: &Value, type_ref: &TypeRef, types: &Types) -> Result<(), TypedDataHashError> {
    match type_ref {
        TypeRef::Bool => match value {
            Value::Bool(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Int => match value {
            Value::Int(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Uint => match value {
            Value::Uint(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::String => match value {
            Value::String(_) => Ok(()),
            _ => Err(TypedDataHashError::InvalidType),
        },
        TypeRef::Array => {
            if let Value::Array(arr) = value {
                if let Some(inner_type) = type_ref.array_type() {
                    for item in arr {
                        validate_value(item, inner_type, types)?;
                    }
                }
                Ok(())
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Map => {
            if let Value::Map(map) = value {
                if let Some(key_type) = type_ref.map_key_type() {
                    if let Some(value_type) = type_ref.map_value_type() {
                        for (key, val) in map {
                            validate_value(key, key_type, types)?;
                            validate_value(val, value_type, types)?;
                        }
                    } else {
                        return Err(TypedDataHashError::InvalidType);
                    }
                } else {
                    return Err(TypedDataHashError::InvalidType);
                }
                Ok(())
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Enum => {
            if let Value::String(s) = value {
                if let Some(enum_type) = types.get(type_ref.name()) {
                    if enum_type.values().contains(s) {
                        Ok(())
                    } else {
                        Err(TypedDataHashError::InvalidEnumValue)
                    }
                } else {
                    Err(TypedDataHashError::InvalidType)
                }
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        TypeRef::Struct => {
            if let Value::Map(map) = value {
                if let Some(struct_type) = types.get(type_ref.name()) {
                    for (key, val) in map {
                        if let Some(field_type) = struct_type.field_type(key) {
                            validate_value(val, field_type, types)?;
                        } else {
                            return Err(TypedDataHashError::InvalidField);
                        }
                    }
                    Ok(())
                } else {
                    Err(TypedDataHashError::InvalidType)
                }
            } else {
                Err(TypedDataHashError::InvalidType)
            }
        },
        _ => Err(TypedDataHashError::InvalidType),
    }
}

use deno_core::OpState;
use deno_os::ops::signal::{op_signal_bind, op_signal_poll};
use deno_os::SignalError;

struct SignalHandler {
    op_state: OpState,
    callbacks: Vec<Box<dyn Fn() + Send + Sync + 'static>>,
}

impl SignalHandler {
    fn new(op_state: OpState) -> Self {
        Self {
            op_state,
            callbacks: Vec::new(),
        }
    }

    fn add_callback<F>(&mut self, cb: F)
    where
        F: Fn() + Send + Sync + 'static,
    {
        self.callbacks.push(Box::new(cb));
    }

    fn trigger_callbacks(&self) {
        for cb in &self.callbacks {
            cb();
        }
    }

    fn bind_signal(&mut self, signal: u32) -> Result<(), SignalError> {
        op_signal_bind(self.op_state.clone(), signal)
    }

    fn poll_signal(&self) -> Result<bool, SignalError> {
        op_signal_poll(self.op_state.clone())
    }
}

fn register_gateway_safe(
    &self,
    dbtx: &mut DatabaseTransaction<'_>,
    gateway: LightningGatewayAnnouncement,
) -> Result<(), Error> {
    // Check for existing gateway with overlapping expiration
    let existing_gateways = LightningGatewayKey::iter(dbtx)
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for existing_key in existing_gateways {
        let existing_announcement = LightningGatewayKey::get(dbtx, &existing_key)?;
        if is_overlap(&existing_announcement, &gateway) {
            return Err(anyhow!("Gateway with overlapping expiration already exists"));
        }
    }

    // Clean up expired gateways
    cleanup_expired_gateways(dbtx)?;

    // Register the new gateway
    LightningGatewayKey::insert(dbtx, &gateway.key, &gateway)?;

    Ok(())
}

fn is_overlap(
    existing: &LightningGatewayAnnouncement,
    new: &LightningGatewayAnnouncement,
) -> bool {
    // Check if the new gateway's time range overlaps with the existing one
    let existing_start = existing.expiry_time;
    let existing_end = existing.expiry_time + existing.expiry_duration;
    let new_start = new.expiry_time;
    let new_end = new.expiry_time + new.expiry_duration;

    // Overlap exists if the intervals [existing_start, existing_end) and [new_start, new_end) intersect
    existing_start < new_end && new_start < existing_end
}

fn cleanup_expired_gateways(
    dbtx: &mut DatabaseTransaction<'_>,
) -> Result<(), Error> {
    let expired_gateways = LightningGatewayKey::iter(dbtx)
        .filter(|(_, announcement)| announcement.expiry_time <= std::time::SystemTime::now())
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for key in expired_gateways {
        LightningGatewayKey::delete(dbtx, &key)?;
    }

    Ok(())
}

use std::fs;
use std::path::{Path, PathBuf};
use serde_json_canonicalizer::pipe;

fn batch_convert_json_to_jcs(directory: &str) -> std::io::Result<()> {
    if !Path::new(directory).exists() {
        return Err(std::io::Error::new(std::io::ErrorKind::NotFound, format!("Directory not found: {}", directory)));
    }

    let entries = fs::read_dir(directory)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext == "json") {
            let content = fs::read_to_string(&path)?;
            let canonicalized = pipe(&content);
            let new_path = path.with_extension("jcs");

            fs::write(new_path, canonicalized)?;
        }
    }

    Ok(())
}

