fn fetch_and_validate_package(registry: &dyn PackageRegistry, spec: PackageSpec) -> PackageResult<PackageSpec> {
    let package = registry.fetch_package(spec)?;
    let package_path = package.path();

    if !package_path.exists() {
        return Err(PackageError::new(eco_format!("Package not found at path: {}", package_path.display())));
    }

    let mut metadata_file = std::fs::File::open(package_path.join("package.typ"))?;
    let mut metadata_content = Vec::new();
    metadata_file.read_to_end(&mut metadata_content)?;

    if metadata_content.is_empty() {
        return Err(PackageError::new(eco_format!("Missing metadata file 'package.typ' in package at: {}", package_path.display())));
    }

    Ok(spec)
}

use std::net::SocketAddr;
use libp2p_core::multiaddr::{Multiaddr, Protocol};

fn multiaddr_to_socketaddr(addr: &Multiaddr) -> Result<SocketAddr, ()> {
    let mut iter = addr.iter();
    let mut host = None;
    let mut port = None;

    while let Some(proto) = iter.next() {
        match proto {
            Protocol::Ip4(ip) => {
                host = Some(ip.to_string());
            }
            Protocol::Ip6(ip) => {
                host = Some(ip.to_string());
            }
            Protocol::Domain(domain) => {
                host = Some(domain.to_string());
            }
            Protocol::Tcp(port) => {
                port = Some(*port);
            }
            _ => {
                // Ignore other protocols
            }
        }
    }

    let host = host.ok_or(())?;
    let port = port.ok_or(())?;

    let socket_addr = SocketAddr::new(
        host.parse().map_err(|_| ())?,
        port,
    );

    Ok(socket_addr)
}

