pub enum Sin {}

fn save_receiver() -> Result<()> {
    let transceiver = Transceiver::new()?;
    let mut file = File::create("received_data.bin")?;

    transceiver.receive(|sin: Sin| {
        if let Some(data) = sin.data() {
            let bytes = bincode::serialize(&data).unwrap();
            file.write_all(&bytes)?;
        }
        Ok(())
    })?;

    Ok(())
}

fn calculate_lightning_liabilities(
    &self,
    dbtx: &mut DatabaseTransaction<'_>,
) -> (Amount, Amount) {
    let (incoming_total, outgoing_total) = dbtx
        .iter_prefix(LightningAuditItemKeyPrefix)
        .map(|item| {
            let key: LightningAuditItemKey = item.key().try_into().unwrap();
            let amount = item.value().amount();
            (key.direction, amount)
        })
        .fold((Amount::ZERO, Amount::ZERO), |(in_total, out_total), (direction, amount)| {
            match direction {
                fedimint_core::LightningAuditDirection::Incoming => (in_total + amount, out_total),
                fedimint_core::LightningAuditDirection::Outgoing => (in_total, out_total + amount),
            }
        });

    (incoming_total, outgoing_total)
}

use crate::ast::{Root, Lambda, Apply};
use crate::match_ast;
use crate::SyntaxNode;

fn extract_functions(root: &Root) -> Vec<Lambda> {
    let mut functions = Vec::new();
    match_ast! { root,
        |Apply { func, .. }| {
            if let Some(lambda) = func.as_ref() {
                if let SyntaxNode::Lambda(lambda) = lambda {
                    functions.push(lambda.clone());
                }
            }
        },
        |Lambda(lambda)| {
            functions.push(lambda.clone());
        }
    };
    functions
}

