fn expand_with_custom_context(doc: &str, custom_context: &str) -> Result<(), Box<dyn Error>> {
    // Create a custom context loader that includes the provided custom context
    let mut context_loader = ContextLoader::new();
    context_loader.add_context(custom_context.parse()?)?;

    // Expand the JSON-LD document using the custom context
    let expanded = CompactJsonLd::expand(
        doc.parse()?,
        &context_loader,
        None,
        None,
        None,
    )?;

    // Optionally, print or process the expanded document
    println!("{:?}", expanded);

    Ok(())
}

use async_trait::async_trait;
use gluesql_core::{data::Schema, error::{Error, Result}, store::Store};
use redis::Commands;
use std::cell::RefCell;

impl RedisStorage {
    pub async fn list_tables_with_creation(&self) -> Result<Vec<(String, Option<String>)>> {
        let mut result = Vec::new();
        let scan_key = Self::redis_generate_scan_schema_key(&self.namespace);
        let schema_keys: Vec<String> = self
            .conn
            .borrow_mut()
            .scan_match(&scan_key)
            .map(|i| i.collect())
            .map_err(|e| Error::StorageMsg(format!("[RedisStorage] failed to scan schemas: {}", e)))?;
        for sk in schema_keys {
            if let Ok(value) = redis::cmd("GET").arg(&sk).query::<String>(&mut self.conn.borrow_mut()) {
                let schema: Schema = serde_json::from_str(&value)
                    .map_err(|e| Error::StorageMsg(format!("[RedisStorage] failed to deserialize schema: {}", e)))?;
                let meta_key = Self::redis_generate_metadata_key(&self.namespace, &schema.table_name, "CREATED");
                let created = match redis::cmd("GET").arg(&meta_key).query::<String>(&mut self.conn.borrow_mut()) {
                    Ok(v) => Some(v),
                    Err(_) => None,
                };
                result.push((schema.table_name, created));
            }
        }
        Ok(result)
    }

    fn redis_generate_scan_schema_key(namespace: &str) -> String {
        format!("schema:{}", namespace)
    }

    fn redis_generate_metadata_key(namespace: &str, table_name: &str, key: &str) -> String {
        format!("metadata:{}:{}:{}", namespace, table_name, key)
    }
}

